/bin/bash -lc "python3 - <<'EOF'
import numpy as np
from PIL import Image
im = np.array(Image.open('first_frame.png').convert('RGB'))
h,w,_ = im.shape
r,g,b = im[...,0].astype(int), im[...,1].astype(int), im[...,2].astype(int)
# 2x2 ascii, classes: wood '.', white 'W', near-black '#', gray by brightness digits
def ch(blk):
    mr,mg,mb = blk[...,0].mean(),blk[...,1].mean(),blk[...,2].mean()
    if mr>60 and mr<150 and mg>40 and mg<115 and mb<85 and mr>=mg and mg>=mb and (mr-mb)>25:
        return '.'
    if mr>140 and mg>125 and mb>120 and abs(mr-mg)<40:
        return 'W'
    if mr<45 and mg<45 and mb<45:
        return '#'
    v=(mr+mg+mb)/3
    return str(min(9,int(v/28)))
for by in range(0,h,2):
    print(f'{by:3d} '+''.join(ch(im[by:by+2,bx:bx+2]) for bx in range(0,w,2)))
EOF"
